const SANYAL_DATA={biography:{name:"Sachindra Nath Sanyal",nativeName:"शचीन्द्रनाथ सान्याल",title:"Mentor of Indian Revolutionaries & Co-Founder of HRA",birthDate:"3 April 1893",birthPlace:"Varanasi, North-Western Provinces, British India",deathDate:"7 February 1942 (Aged 48)",deathPlace:"Gorakhpur, United Provinces, British India",movement:"Indian Independence Movement • Armed Revolutionary Struggle",organisations:"Anushilan Samiti (Varanasi Branch), Ghadar Party Connection, Hindustan Republican Association (HRA)",imprisonment:"Cellular Jail (Andaman Islands) twice: Benares Conspiracy Case (1915) & Kakori Conspiracy Case (1925)",nickname:"The Architect of Revolutionary Nationalism",summary:"Sachindra Nath Sanyal was a visionary revolutionary leader, ideologue, and author who bridged early 20th-century Bengali revolutionary organizations (Anushilan Samiti) with the northern Indian revolutionary surge of the 1920s. As co-founder of the Hindustan Republican Association (HRA), his seminal book 'Bandi Jeevan' served as the operational and ideological manual for a generation of freedom fighters, including Bhagat Singh and Chandrashekhar Azad."},quickStats:[{label:"Lifespan",value:"1893–1942",icon:"🕊️",subtext:"48 Years Dedicated to Freedom"},{label:"Key Founding",value:"HRA (1924)",icon:"🚩",subtext:"Hindustan Republican Association"},{label:"Kalapani Exile",value:"Cellular Jail",icon:"🏛️",subtext:"Imprisoned Twice in Andaman"},{label:"Masterpiece",value:"Bandi Jeevan",icon:"📖",subtext:"Bible of Indian Revolutionaries"}],timeline:[{year:"1893",title:"Birth in Varanasi",category:"Early Life",description:"Sachindra Nath Sanyal is born on April 3, 1893, in Varanasi into a patriotic Bengali family. From an early age, he is deeply inspired by Swami Vivekananda and the Swadeshi Movement."},{year:"1913",title:"Establishing Anushilan Samiti in Varanasi",category:"Revolutionary Roots",description:"Founds the Varanasi branch of Anushilan Samiti. He connects with legendary leader Rash Behari Bose to expand armed revolutionary secret societies across Northern India."},{year:"1915",title:"Ghadar Mutiny & Benares Conspiracy Case",category:"Armed Struggle",description:"Plays a central role in organizing the pan-Indian Ghadar Mutiny of February 1915 alongside Rash Behari Bose. Following the plot's betrayal, Sanyal is tried in the Benares Conspiracy Case and sentenced to life imprisonment at Cellular Jail (Kalapani)."},{year:"1920",title:"Royal Amnesty Release & Writing 'Bandi Jeevan'",category:"Literary Impact",description:"Released following the post-WWI Royal Amnesty declaration. He writes his iconic memoir 'Bandi Jeevan' (Life of a Captive), which quickly becomes the most widely circulated underground book among Indian revolutionaries."},{year:"1924",title:"Founding the Hindustan Republican Association (HRA)",category:"HRA Formation",description:"In October 1924, Sanyal convenes a historic conference in Kanpur along with Ram Prasad Bismil, Jogesh Chandra Chatterji, and Sachindra Nath Bakshi, establishing the HRA with the goal of founding a Federal Republic of the United States of India."},{year:"1925",title:"Drafting 'The Revolutionary' Manifesto & Kakori Action",category:"HRA Manifesto",description:"Drafts and distributes 'The Revolutionary', the official 4-page yellow paper manifesto of the HRA across North Indian cities on January 1, 1925. Following the Kakori Train Action in August 1925, he is re-arrested."},{year:"1927",title:"Second Exile to Cellular Jail (Kalapani)",category:"Trial & Imprisonment",description:"Sentenced to transportation for life in the Kakori Conspiracy Case trial. He is sent back to the Andaman Cellular Jail, enduring harsh labor and isolation."},{year:"1937",title:"Release under Congress Provincial Ministries",category:"Final Years",description:"Released when Provincial Autonomy governments take office in 1937. He resumes anti-imperialist journalism, organizing labor, and mentoring anti-colonial youth."},{year:"1940–1942",title:"Final Imprisonment & Martyrdom",category:"Martyrdom",description:"Re-arrested during World War II for advocating anti-British rebellion. Contracts severe tuberculosis under harsh prison conditions and attains martyrdom on February 7, 1942, in Gorakhpur Jail."}],hraHistory:{title:"The Rise of the Hindustan Republican Association (HRA)",subtitle:"India's First Pan-Northern Armed Revolutionary Republic Movement",foundingDate:"October 1924",foundingLocation:"Kanpur, Uttar Pradesh",founders:["Sachindra Nath Sanyal","Ram Prasad Bismil","Jogesh Chandra Chatterji","Sachindra Nath Bakshi"],coreObjective:"To establish a secular, socialist, and democratic 'Federal Republic of the United States of India' through an organized armed revolution against British rule.",pillars:[{title:"Democratic Federalism",icon:"🏛️",description:"HRA rejected monarchical or dictatorial ambitions, advocating a federal constitutional republic governed by universal adult franchise."},{title:"Anti-Exploitation & Social Equality",icon:"⚖️",description:"Recognized that true freedom required ending capitalism-based economic exploitation of workers and peasants alongside British political rule."},{title:"Secular National Unity",icon:"🤝",description:"Formed a united front bridging Hindu and Muslim youth (symbolized by the deep bond between Bismil and Ashfaqulla Khan) to combat British divide-and-rule policies."},{title:"Revolutionary Cadre Training",icon:"🔥",description:"Built a disciplined, secret network across UP, Bihar, Punjab, Bengal, and Delhi that mentored younger leaders like Bhagat Singh, Chandrashekhar Azad, and Sukhdev."}],evolutionToHSRA:"Following Sanyal's and Bismil's arrests in the Kakori Case, young leaders Chandrashekhar Azad, Bhagat Singh, Sukhdev, and Shiv Verma reorganized the association at Feroz Shah Kotla in Delhi in 1928, renaming it the **Hindustan Socialist Republican Association (HSRA)** to explicitly emphasize socialist restructuring."},writings:[{title:"Bandi Jeevan (बंदी जीवन / Life of a Captive)",year:"1922",type:"Autobiographical & Revolutionary Treatise",significance:"Considered the 'Bible' of 1920s Indian revolutionaries.",description:"Written after Sanyal's first release from Cellular Jail, 'Bandi Jeevan' detailed his experiences in Kalapani, political philosophies of liberation, and tactical approaches to anti-colonial revolution. It was translated into Hindi, Gurmukhi, Marathi, and Tamil. Bhagat Singh personally carried and distributed copies among youth.",excerpt:"Freedom cannot be achieved by begging or petitioning; it must be won through supreme sacrifice, ideological clarity, and unyielding struggle against tyranny."},{title:"The Revolutionary (घोषणा पत्र / HRA Manifesto)",year:"1925",type:"Official Political Manifesto",significance:"The constitutional blueprint of the HRA.",description:"Drafted by Sanyal under the pseudonym 'Vijay Kumar' and printed on distinct yellow paper, this 4-page manifesto was secretly posted across major cities in North India on January 1, 1925. It proclaimed the HRA's goal of creating a Federal Republic and condemned economic exploitation.",excerpt:"The object of the Association shall be to establish a Federal Republic of the United States of India by an organized and armed revolution... In this Republic, all social and economic exploitation shall cease."},{title:"Vichar Mala & Philosophical Essays",year:"1920–1935",type:"Ideological Essays",significance:"Philosophical grounding of revolutionary action.",description:"A collection of essays examining the synthesis of Indian spiritual heritage with modern social democracy, analyzing why non-violent petitioning alone was inadequate against British imperial firepower.",excerpt:"A revolution is not a mere riot; it is the rebirth of a nation's soul striving for absolute justice and human dignity."}],gallery:[{title:"Portrait of Sachindra Nath Sanyal",caption:"Sachindra Nath Sanyal (1893–1942), co-founder of HRA and author of Bandi Jeevan.",image:"https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=80",category:"Portrait"},{title:"Cellular Jail (Kalapani), Andaman",caption:"The high-security British penal colony where Sanyal was exiled twice during his lifetime.",image:"https://images.unsplash.com/photo-1590076175571-4b5459efb099?auto=format&fit=crop&w=1000&q=80",category:"Imprisonment"},{title:"HRA Manifesto 'The Revolutionary' (1925)",caption:"Historic 4-page yellow paper manifesto issued on January 1, 1925, laying out the vision for a Federal Republic.",image:"https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&w=1000&q=80",category:"Documents"},{title:"Kanpur Revolutionaries Assembly Site",caption:"Historic location in Kanpur where Sanyal, Bismil, Chatterji, and Bakshi founded HRA in October 1924.",image:"https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1000&q=80",category:"Historic Site"},{title:"Original Printing of 'Bandi Jeevan'",caption:"Cover of Sanyal's classic memoir which served as the guiding handbook for Bhagat Singh and Chandrashekhar Azad.",image:"https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=1000&q=80",category:"Literature"},{title:"Kakori Conspiracy Trial Archives",caption:"Court documents and intelligence reports from the 1925 Kakori trial in which Sanyal received life imprisonment.",image:"https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&fit=crop&w=1000&q=80",category:"Archives"}],references:[{source:"Bandi Jeevan (Life of a Captive)",author:"Sachindra Nath Sanyal",year:"1922 (First Edition)",type:"Primary Memoir",notes:"Autobiographical account detailing the Anushilan movement, Ghadar conspiracy, and torture at Cellular Jail."},{source:"The Revolutionary (HRA Official Manifesto)",author:"Hindustan Republican Association (S. N. Sanyal)",year:"1925",type:"Historical Document",notes:"Official manifesto of HRA outlining democratic federalism, published on 1 January 1925."},{source:"Terrorism in India 1917–1936 (Intelligence Bureau Reports)",author:"Home Department, Government of British India",year:"1937",type:"Colonial Intelligence Record",notes:"British intelligence files identifying Sanyal as the 'intellectual chief and master organizer' of North Indian armed groups."},{source:"Bhagat Singh & His Comrades: The Ideological Genesis",author:"Prof. Chaman Lal / National Archives of India",year:"2007",type:"Academic Research",notes:"Documents Sanyal's direct mentorship of Bhagat Singh, Sukhdev, and Chandrashekhar Azad."},{source:"They Died That India Might Live",author:"K. C. Ghosh",year:"1965",type:"Historical Retrospective",notes:"Detailed record of trials, Kakori sentence, and revolutionary martyrs of the 1920s."}],quotes:[{quote:"Sanyal Ji's 'Bandi Jeevan' was not merely a book for us; it was our operational guide, our moral compass, and our spiritual strength during underground days.",speaker:"Bhagat Singh",context:"Reflecting on his early revolutionary influences in Lahore"},{quote:"We do not seek blood for the sake of violence. We seek to dismantle an unnatural imperial tyranny so that human freedom and equality may flourish in India.",speaker:"Sachindra Nath Sanyal",context:"Excerpt from 'The Revolutionary' Manifesto (1925)"},{quote:"Sachindra Nath Sanyal was the living bridge between the early pioneers of Bengal's Anushilan Samiti and the fierce young revolutionaries of the North who transformed HRA into HSRA.",speaker:"Ram Prasad Bismil",context:"From Bismil's Autobiography written in Gorakhpur Jail"}],quizQuestions:[{question:"In which year did Sachindra Nath Sanyal co-found the Hindustan Republican Association (HRA)?",options:["1915 in Calcutta","1924 in Kanpur","1930 in Lahore","1942 in Delhi"],correct:1,explanation:"Sanyal co-founded the HRA in October 1924 during a historic meeting in Kanpur alongside Ram Prasad Bismil and Jogesh Chandra Chatterji."},{question:"Which iconic book written by Sachindra Nath Sanyal became known as the 'Bible of Indian Revolutionaries'?",options:["Anandamath","Bandi Jeevan (Life of a Captive)","Pather Dabi","Discovery of India"],correct:1,explanation:"'Bandi Jeevan', written after Sanyal's first release from Cellular Jail in 1920, was widely read and distributed by young revolutionaries including Bhagat Singh."},{question:"What was the name of the official 1925 HRA manifesto drafted by Sanyal?",options:["The Revolutionary","Vande Mataram","Swarajya Patrika","India House Bulletin"],correct:0,explanation:"Sanyal drafted 'The Revolutionary' under the pseudonym Vijay Kumar, distributing it on distinct yellow paper on January 1, 1925."},{question:"How many times was Sachindra Nath Sanyal sentenced to life imprisonment in the Cellular Jail (Kalapani)?",options:["Never","Once (1915)","Twice (1915 Benares Conspiracy & 1925 Kakori Case)","Three times"],correct:2,explanation:"Sanyal was uniquely exiled to the Andaman Cellular Jail twice: first in 1915 for the Benares Conspiracy Case and again in 1927 for the Kakori Case."},{question:"What ultimate vision for India did Sanyal and the HRA proclaim in their constitution?",options:["A constitutional monarchy under British crown","A Federal Republic of the United States of India with universal franchise","A military dictatorship","A division into princely states"],correct:1,explanation:"HRA's manifesto declared the goal of creating a 'Federal Republic of the United States of India' based on universal adult franchise and social equality."}]};